import React, { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};  // '/settings'에서 전달된 값
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [error, setError] = useState(null);
  const [isRecording, setIsRecording] = useState(false);  // 음성 녹음 상태 추가
  const [audioResponse, setAudioResponse] = useState(null); // 챗봇 음성 응답 추가
  const chatEndRef = useRef(null);  // 맨 밑의 메시지 참조용
  const mediaRecorderRef = useRef(null);  // MediaRecorder 객체 참조

  // 현재 시간 가져오기
  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',  // 요일을 포함하도록 설정
    });
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false, // 24시간 형식
    });

    return `${date} ${time}`;
  };

  const getTimeOnly = () => {
    const now = new Date();
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    return time;
  };

  // 메시지 전송 함수
  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    const sentTime = getTimeOnly();
    const newMessage = { sender: "사용자", message: userInput, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);
    setUserInput("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          chatbotName: chatbotName,
          user_input: userInput,
          personality: personality,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "오류가 발생했습니다.");
      }

      const data = await response.json();
      const chatbotMessage = data.response;

      const receivedTime = getTimeOnly();
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: chatbotName || chatbotName, message: chatbotMessage, time: receivedTime },
      ]);

      // TTS 응답 처리
      if (data.audio_base64) {
        setAudioResponse(data.audio_base64);
      }
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError(error.message);
    }
  };

  // 음성 녹음 시작
  const startRecording = () => {
    setIsRecording(true);
    navigator.mediaDevices.getUserMedia({ audio: true })
      .then(stream => {
        const mediaRecorder = new MediaRecorder(stream);
        mediaRecorderRef.current = mediaRecorder;  // MediaRecorder 객체 저장
        mediaRecorder.start();

        mediaRecorder.ondataavailable = async (event) => {
          const audioBlob = event.data;
          const audioFile = new File([audioBlob], 'audio.mp3');
          const formData = new FormData();
          formData.append("audio", audioFile);

          try {
            const sttResponse = await fetch(`${process.env.REACT_APP_API_URL}/stt`, {
              method: 'POST',
              body: formData,
            });
            const sttData = await sttResponse.json();

            if (sttData.transcript) {
              setUserInput(sttData.transcript);
              handleSendMessage();
            }
          } catch (error) {
            console.error("STT error:", error);
          }
        };

        mediaRecorder.onstop = () => {
          stream.getTracks().forEach(track => track.stop());
          setIsRecording(false);
        };
      })
      .catch(err => console.error("Error accessing the microphone:", err));
  };

  // 음성 녹음 중지
  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
    }
  };

  // 실시간으로 현재 시간 갱신
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  // 채팅이 끝날 때 자동으로 스크롤
  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chatHistory]);

  // 키보드로 엔터를 누르면 메시지 전송
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatDataTime}>
        <strong>{currentDateTime}</strong>
      </div>
      <div className={styles.chatHistory}>
        {chatHistory.map((chat, index) => (
          <div
            key={index}
            className={chat.sender === '사용자' ? styles.chatMessageUser : styles.chatMessageChatbot}
          >
            <strong>{chat.sender === "사용자" ? "사용자" : chatbotName}:</strong>
            <div>{chat.message}</div>
            <div className={chat.sender === '사용자' ? styles.chatTimeUser : styles.chatTimeChatbot}>
              <em>{chat.time}</em>
            </div>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}
        />
        <button className={styles.chatSendButton} onClick={handleSendMessage}>전송</button>
        <button onClick={startRecording} disabled={isRecording}>녹음 시작</button>
        <button onClick={stopRecording} disabled={!isRecording}>녹음 중지</button>
      </div>
      {/* TTS 음성 응답 추가 */}
      {audioResponse && (
        <div className={styles.audioResponse}>
          <audio controls autoPlay>
            <source src={`data:audio/mp3;base64,${audioResponse}`} type="audio/mp3" />
          </audio>
        </div>
      )}
    </div>
  );
};

export default Chat;
